CREATE TABLE currencies (code VARCHAR(3) PRIMARY KEY, name VARCHAR(100) NOT NULL, rate DECIMAL(20,8) NOT NULL CHECK(rate>0));
INSERT INTO currencies VALUES ('USD','دالر امریکایی',1);
CREATE TABLE categories (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(160) NOT NULL UNIQUE);
CREATE TABLE parties (id BIGINT AUTO_INCREMENT PRIMARY KEY, kind VARCHAR(20) NOT NULL, name VARCHAR(160) NOT NULL, phone VARCHAR(60) NOT NULL DEFAULT '', address VARCHAR(500) NOT NULL DEFAULT '', active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE products (id BIGINT AUTO_INCREMENT PRIMARY KEY, code VARCHAR(60) NOT NULL UNIQUE, name VARCHAR(180) NOT NULL, category_id BIGINT, unit VARCHAR(40) NOT NULL, purchase_price DECIMAL(20,4) NOT NULL, sale_price DECIMAL(20,4) NOT NULL, stock DECIMAL(20,4) NOT NULL DEFAULT 0, min_stock DECIMAL(20,4) NOT NULL DEFAULT 0, active BOOLEAN NOT NULL DEFAULT TRUE, FOREIGN KEY(category_id) REFERENCES categories(id));
CREATE TABLE employees (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(160) NOT NULL, phone VARCHAR(60) NOT NULL DEFAULT '', position VARCHAR(100) NOT NULL DEFAULT '', salary DECIMAL(20,4) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE app_users (id BIGINT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(80) NOT NULL UNIQUE, password VARCHAR(100) NOT NULL, name VARCHAR(160) NOT NULL, role VARCHAR(20) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE invoices (id BIGINT AUTO_INCREMENT PRIMARY KEY, request_key VARCHAR(36) NOT NULL UNIQUE, kind VARCHAR(20) NOT NULL, party_id BIGINT NOT NULL, invoice_date DATE NOT NULL, currency VARCHAR(3) NOT NULL, rate DECIMAL(20,8) NOT NULL, subtotal DECIMAL(20,4) NOT NULL, discount DECIMAL(20,4) NOT NULL, total DECIMAL(20,4) NOT NULL, total_usd DECIMAL(20,4) NOT NULL, cost_usd DECIMAL(20,4) NOT NULL DEFAULT 0, notes VARCHAR(1000) NOT NULL DEFAULT '', voided BOOLEAN NOT NULL DEFAULT FALSE, created_by VARCHAR(80) NOT NULL, FOREIGN KEY(party_id) REFERENCES parties(id), FOREIGN KEY(currency) REFERENCES currencies(code));
CREATE TABLE invoice_items (id BIGINT AUTO_INCREMENT PRIMARY KEY, invoice_id BIGINT NOT NULL, product_id BIGINT NOT NULL, name VARCHAR(180) NOT NULL, unit VARCHAR(40) NOT NULL, quantity DECIMAL(20,4) NOT NULL, price DECIMAL(20,4) NOT NULL, cost_price DECIMAL(20,4) NOT NULL, total DECIMAL(20,4) NOT NULL, FOREIGN KEY(invoice_id) REFERENCES invoices(id), FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE payments (id BIGINT AUTO_INCREMENT PRIMARY KEY, request_key VARCHAR(36) NOT NULL UNIQUE, party_id BIGINT NOT NULL, invoice_id BIGINT, payment_date DATE NOT NULL, currency VARCHAR(3) NOT NULL, rate DECIMAL(20,8) NOT NULL, amount DECIMAL(20,4) NOT NULL, amount_usd DECIMAL(20,4) NOT NULL, notes VARCHAR(1000) NOT NULL DEFAULT '', created_by VARCHAR(80) NOT NULL, FOREIGN KEY(party_id) REFERENCES parties(id), FOREIGN KEY(invoice_id) REFERENCES invoices(id), FOREIGN KEY(currency) REFERENCES currencies(code));
CREATE TABLE expenses (id BIGINT AUTO_INCREMENT PRIMARY KEY, request_key VARCHAR(36) NOT NULL UNIQUE, expense_date DATE NOT NULL, category VARCHAR(100) NOT NULL, currency VARCHAR(3) NOT NULL, rate DECIMAL(20,8) NOT NULL, amount DECIMAL(20,4) NOT NULL, amount_usd DECIMAL(20,4) NOT NULL, notes VARCHAR(1000) NOT NULL DEFAULT '', employee_id BIGINT, salary_month VARCHAR(7), created_by VARCHAR(80) NOT NULL, FOREIGN KEY(currency) REFERENCES currencies(code), FOREIGN KEY(employee_id) REFERENCES employees(id), UNIQUE(employee_id,salary_month));
CREATE TABLE stock_movements (id BIGINT AUTO_INCREMENT PRIMARY KEY, product_id BIGINT NOT NULL, invoice_id BIGINT, movement_date DATE NOT NULL, quantity DECIMAL(20,4) NOT NULL, notes VARCHAR(500) NOT NULL, FOREIGN KEY(product_id) REFERENCES products(id), FOREIGN KEY(invoice_id) REFERENCES invoices(id));
CREATE TABLE settings (id INT PRIMARY KEY, company_name VARCHAR(160) NOT NULL, phone VARCHAR(100) NOT NULL, address VARCHAR(500) NOT NULL, brands VARCHAR(500) NOT NULL, terms VARCHAR(1000) NOT NULL, header_image MEDIUMTEXT, logo_image MEDIUMTEXT);
INSERT INTO settings VALUES (1,'امینی گروپ','','','','اجناس را هنگام تسلیمی بررسی نمایید.','','');
CREATE TABLE content (id BIGINT AUTO_INCREMENT PRIMARY KEY, kind VARCHAR(30) NOT NULL, title VARCHAR(180) NOT NULL, body TEXT NOT NULL, image MEDIUMTEXT, published BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE messages (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(160) NOT NULL, email VARCHAR(200) NOT NULL, phone VARCHAR(60) NOT NULL, subject VARCHAR(180) NOT NULL, message TEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE audit_log (id BIGINT AUTO_INCREMENT PRIMARY KEY, actor VARCHAR(80) NOT NULL, action VARCHAR(100) NOT NULL, entity_id BIGINT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_invoice_party ON invoices(party_id,invoice_date);
CREATE INDEX idx_payment_party ON payments(party_id,payment_date);
CREATE INDEX idx_expense_date ON expenses(expense_date);
